// Animated number counter
export function Counter({ value, decimals = 0, prefix = "", suffix = "" }:
 { value: number; decimals?: number; prefix?: string; suffix?: string; }) {
 const [n, setN] = React.useState(0);
 React.useEffect(() => {
 let raf = 0; const start = performance.now(); const dur = 900;
 const tick = (t: number) => {
 const p = Math.min(1, (t - start) / dur);
 const e = 1 - Math.pow(1 - p, 3);
 setN(value * e);
 if (p < 1) raf = requestAnimationFrame(tick);
 };
 raf = requestAnimationFrame(tick);
 return () => cancelAnimationFrame(raf);
 }, [value]);
 return <span className="ci-num">{prefix}{n.toLocaleString(undefined, { minimumFractionDigits: decimals, maximumFractionDigits: decimals })}{suffix}</span>;
}

// Sparkline SVG
export function Sparkline({ data, color = "var(--ci-cyan)", h = 30, fill = true }:
 { data: number[]; color?: string; h?: number; fill?: boolean; }) {
 const w = 120, max = Math.max(...data), min = Math.min(...data), rng = max - min || 1;
 const pts = data.map((v, i) => [(i / (data.length - 1)) * w, h - ((v - min) / rng) * (h - 4) - 2]);
 const line = pts.map((p, i) => (i ? "L" : "M") + p[0].toFixed(1) + " " + p[1].toFixed(1)).join(" ");
 const gid = "sg" + color.replace(/[^a-z0-9]/gi, "");
 return (
 <svg className="ci-kpi__spark" viewBox={`0 0 ${w} ${h}`} preserveAspectRatio="none" style={{ width: "100%" }}>
 <defs>
 <linearGradient id={gid} x1="0" y1="0" x2="0" y2="1">
 <stop offset="0%" stopColor={color} stopOpacity="0.35" />
 <stop offset="100%" stopColor={color} stopOpacity="0" />
 </linearGradient>
 </defs>
 {fill && <path d={`${line} L ${w} ${h} L 0 ${h} Z`} fill={`url(#${gid})`} />}
 <path d={line} fill="none" stroke={color} strokeWidth="1.8" strokeLinecap="round" />
 </svg>
 );
}
