","import React from "react";
import { PipeStage } from "../../data/command";

// Connected funnel / Sankey-style ribbon with conversion necks + leakage highlight.
export function PipelineFunnel({ stages, leakIndex, selected, onSelect }:
 { stages: PipeStage[]; leakIndex: number; selected: string | null; onSelect: (k: string) => void }) {
 const [tip, setTip] = React.useState<{ x: number; y: number; i: number } | null>(null);

 const W = 780, H = 184, padL = 44, padR = 44, cy = 100, half = 52;
 const n = stages.length, innerW = W - padL - padR, step = innerW / (n - 1);
 const max = stages[0].value;
 const hh = (v: number) => Math.max(7, Math.pow(v / max, 0.34) * half);
 const X = (i: number) => padL + i * step;
 const conv = (i: number) => Math.round((stages[i + 1].value / stages[i].value) * 100);
 const prevDelta = [-2, -1, 4, -3, 1, 2];
 const fmt = (v: number) => (v >= 1000 ? (v / 1000).toFixed(v >= 100000 ? 0 : 1) + "k" : "" + v);

 const topPath = stages.map((s, i) => `${i ? "L" : "M"}${X(i).toFixed(1)},${(cy - hh(s.value)).toFixed(1)}`).join(" ");
 const botPath = stages.map((s, i) => `${X(i).toFixed(1)},${(cy + hh(s.value)).toFixed(1)}`).reverse().join(" L ");
 const fill = `${topPath} L ${botPath} Z`;

 return (
 <div className="cc-funnel" style={{ position: "relative" }}>
 <svg className="ci-chart" viewBox={`0 0 ${W} ${H}`} onMouseLeave={() => setTip(null)}>
 <defs>
 <linearGradient id="funnelGrad" x1="0" y1="0" x2="1" y2="0">
 <stop offset="0%" stopColor="#0a99c7" stopOpacity="0.30" />
 <stop offset="100%" stopColor="#2f6fed" stopOpacity="0.42" />
 </linearGradient>
 </defs>

 {/* continuous funnel body */}
 <path d={fill} fill="url(#funnelGrad)" stroke="rgba(47,111,237,0.35)" strokeWidth="1" />

 {/* leakage segment highlight */}
 {(() => {
 const i = leakIndex;
 const seg = `M${X(i)},${cy - hh(stages[i].value)} L${X(i + 1)},${cy - hh(stages[i + 1].value)} L${X(i + 1)},${cy + hh(stages[i + 1].value)} L${X(i)},${cy + hh(stages[i].value)} Z`;
 return <path d={seg} fill="rgba(217,130,10,0.14)" stroke="rgba(217,130,10,0.55)" strokeWidth="1" strokeDasharray="4 3" />;
 })()}

 {/* conversion necks */}
 {stages.slice(0, -1).map((s, i) => (
 <text key={"c" + i} x={(X(i) + X(i + 1)) / 2} y={16} textAnchor="middle"
 fontSize="11" fontWeight="800" fill={i === leakIndex ? "#d9820a" : "#45577a"}>{conv(i)}%</text>
 ))}

 {/* stage nodes */}
 {stages.map((s, i) => {
 const dim = selected && selected !== s.key;
 const sel = selected === s.key;
 return (
 <g key={s.key} style={{ cursor: "pointer", opacity: dim ? 0.4 : 1, transition: "opacity .15s" }}
 onClick={() => onSelect(s.key)}
 onMouseMove={e => i < n - 1 && setTip({ x: e.clientX, y: e.clientY, i })}>
 <line x1={X(i)} y1={cy - hh(s.value)} x2={X(i)} y2={cy + hh(s.value)}
 stroke={sel ? "#0a99c7" : "#ffffff"} strokeWidth={sel ? 2.5 : 1.5} />
 <text x={X(i)} y={cy - hh(s.value) - 7} textAnchor="middle" fontSize="12.5" fontWeight="800" fill="#10213f">{fmt(s.value)}</text>
 <text x={X(i)} y={H - 20} textAnchor="middle" fontSize="9.5" fontWeight="600" fill="#45577a">{s.label.split(" ")[0]}</text>
 {s.label.split(" ")[1] && <text x={X(i)} y={H - 9} textAnchor="middle" fontSize="9.5" fontWeight="600" fill="#45577a">{s.label.split(" ").slice(1).join(" ")}</text>}
 <rect x={X(i) - step / 2} y={30} width={step} height={H - 60} fill="transparent" />
 </g>
 );
 })}
 </svg>
 {tip && (
 <div className="ci-tip__pop" style={{ left: tip.x + 12, top: tip.y - 10 }}>
 <b>{stages[tip.i].label} → {stages[tip.i + 1].label}</b><br />
 <span className="ci-faint">Progressing {stages[tip.i + 1].value.toLocaleString()} · Dropping {(stages[tip.i].value - stages[tip.i + 1].value).toLocaleString()}</span><br />
 <span className="ci-faint">Conversion {conv(tip.i)}% · {prevDelta[tip.i] >= 0 ? "+" : ""}{prevDelta[tip.i]}pts vs prev period</span>
 </div>
 )}
 </div>
 );
}
