","import React from "react";
import { Panel } from "../primitives";
import { Chip } from "../KpiCard";
import { PageHead } from "../common";
import { Button } from "../Button";
import { AthleteTable } from "../AthleteTable";
import { useApp } from "../../context/AppContext";
import { ATHLETES, Athlete } from "../../data/demo";

const SEGMENTS = ["All", "High Potential", "At Risk", "Talent Transfer", "Paralympic"];

export function Athletes({ onAthlete }: { onAthlete: (a: Athlete) => void }) {
 const { navigate } = useApp();
 const [seg, setSeg] = React.useState("All");
 const [q, setQ] = React.useState("");

 const rows = ATHLETES.filter(a => {
 if (q && !a.name.toLowerCase().includes(q.toLowerCase())) return false;
 if (seg === "High Potential") return a.potential > 84;
 if (seg === "At Risk") return a.injuryRisk > 55;
 if (seg === "Talent Transfer") return a.stage === "Talent Transfer" || a.pathway === "Transfer";
 if (seg === "Paralympic") return a.stage === "Paralympic" || a.sport === "Para-Athletics";
 return true;
 });

 return (
 <div className="ci-fade">
 <PageHead title="Athletes" desc="The full tracked population across every stage and pathway. Search, segment and drill into any athlete's 360° profile."
 actions={<Button icon="user" variant="primary" onClick={() => navigate("athlete360")}>Open Athlete 360</Button>} />

 <Panel hover title={`${rows.length} athletes`} sub="Click a row to open the profile drawer"
 right={
 <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
 <div className="ci-search" style={{ minWidth: 200, padding: "6px 12px" }}>
 <input placeholder="Search name…" value={q} onChange={e => setQ(e.target.value)} aria-label="Search athletes" />
 </div>
 <div className="ci-seg">
 {SEGMENTS.map(s => (
 <button key={s} className={`ci-seg__btn ${seg === s ? "ci-seg__btn--active" : ""}`} onClick={() => setSeg(s)}>{s}</button>
 ))}
 </div>
 </div>
 }>
 <AthleteTable rows={rows} onSelect={onAthlete} />
 </Panel>
 </div>
 );
}
","/* ============================================================
 Athlete 360 — cockpit styles (PREMIUM LIGHT)
 ============================================================ */

/* Hero */
.a360-hero {
 display: flex; align-items: center; gap: 18px; flex-wrap: wrap;
 padding: 16px 18px; margin-bottom: 13px; border-radius: var(--ci-radius);
 border: 1px solid var(--ci-border); box-shadow: var(--ci-shadow-soft);
 background: linear-gradient(120deg, #ffffff 0%, #f2f7ff 55%, #eef4ff 100%);
 position: relative; overflow: hidden;
}
.a360-hero::after { content: ""; position: absolute; right: -40px; top: -40px; width: 220px; height: 220px;
 background: radial-gradient(circle, rgba(10,153,199,0.12), transparent 70%); pointer-events: none; }
.a360-photo {
 width: 76px; height: 76px; border-radius: 18px; flex: none; display: grid; place-items: center;
 font-size: 26px; font-weight: 800; color: #fff; background: var(--ci-grad-cyan);
 box-shadow: 0 6px 16px rgba(10,153,199,0.32);
}
.a360-id { min-width: 200px; }
.a360-id__name { font-size: 20px; font-weight: 800; line-height: 1.1; }
.a360-id__meta { font-size: 12px; color: var(--ci-text-dim); margin-top: 3px; }
.a360-id__chips { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 8px; }
.a360-hero__stats { display: flex; gap: 20px; flex-wrap: wrap; margin-left: auto; }
.a360-stat { text-align: center; }
.a360-stat__v { font-size: 20px; font-weight: 800; line-height: 1; }
.a360-stat__l { font-size: 9.5px; color: var(--ci-text-faint); text-transform: uppercase; letter-spacing: 0.05em; margin-top: 3px; }
.a360-hero__actions { display: flex; gap: 7px; flex-wrap: wrap; width: 100%; margin-top: 4px; }

/* attribute comparison bars */
.a360-attr { display: flex; align-items: center; gap: 10px; margin-bottom: 7px; }
.a360-attr__label { width: 96px; flex: none; font-size: 11px; color: var(--ci-text-dim); }
.a360-attr__bar { flex: 1; position: relative; height: 8px; border-radius: 5px; background: rgba(18,38,78,0.07); overflow: visible; }
.a360-attr__fill { height: 100%; border-radius: 5px; background: var(--ci-grad-cyan); }
.a360-attr__gap { position: absolute; top: -3px; width: 2px; height: 14px; background: var(--ci-violet); }
.a360-attr__pct { width: 60px; flex: none; text-align: right; font-size: 10.5px; color: var(--ci-text-faint); font-variant-numeric: tabular-nums; }

/* wearable rows */
.a360-wear { display: flex; align-items: center; gap: 10px; padding: 7px 0; border-bottom: 1px solid var(--ci-grid-line); }
.a360-wear:last-child { border-bottom: none; }
.a360-wear__l { flex: 1; min-width: 0; }
.a360-wear__lab { font-size: 11.5px; color: var(--ci-text-dim); }
.a360-wear__val { font-size: 14px; font-weight: 800; color: var(--ci-text); }
.a360-wear__spark { width: 70px; flex: none; height: 22px; }

/* milestone timeline */
.a360-mile { display: flex; align-items: stretch; gap: 0; }
.a360-mile__step { flex: 1; text-align: center; position: relative; padding: 0 4px; }
.a360-mile__dot { width: 18px; height: 18px; border-radius: 50%; margin: 0 auto 8px; display: grid; place-items: center;
 border: 2px solid var(--ci-border-strong); background: #fff; position: relative; z-index: 1; }
.a360-mile__dot--done { background: var(--ci-cyan); border-color: var(--ci-cyan); }
.a360-mile__dot--next { border-color: var(--ci-amber); background: var(--ci-amber-soft); box-shadow: 0 0 0 4px rgba(217,130,10,0.14); }
.a360-mile__line { position: absolute; top: 9px; left: 50%; width: 100%; height: 2px; background: var(--ci-border); z-index: 0; }
.a360-mile__line--done { background: var(--ci-cyan); }
.a360-mile__label { font-size: 11px; font-weight: 700; color: var(--ci-text); }
.a360-mile__date { font-size: 10px; color: var(--ci-text-faint); }
.a360-mile__note { font-size: 10px; color: var(--ci-text-dim); margin-top: 3px; line-height: 1.25; }

/* next best action banner */
.a360-nba { border: 1px solid rgba(10,153,199,0.3); border-radius: var(--ci-radius);
 background: linear-gradient(120deg, rgba(10,153,199,0.10), rgba(47,111,237,0.05)); padding: 15px 16px; height: 100%; }
.a360-nba__k { font-size: 10px; font-weight: 800; letter-spacing: 0.14em; text-transform: uppercase; color: var(--ci-cyan); }
.a360-nba__title { font-size: 17px; font-weight: 800; margin: 6px 0 6px; color: var(--ci-text); }
.a360-nba__why { font-size: 12px; color: var(--ci-text-dim); line-height: 1.45; margin-bottom: 10px; }
.a360-nba__ev { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 12px; }
.a360-ev { background: #fff; border: 1px solid var(--ci-border); border-radius: 9px; padding: 6px 10px; }
.a360-ev__v { font-size: 15px; font-weight: 800; }
.a360-ev__l { font-size: 9.5px; color: var(--ci-text-faint); text-transform: uppercase; letter-spacing: 0.04em; }

/* intervention timeline */
.a360-int { display: flex; gap: 10px; padding: 8px 0; border-bottom: 1px solid var(--ci-grid-line); cursor: pointer; }
.a360-int:last-child { border-bottom: none; }
.a360-int:hover .a360-int__reason { color: var(--ci-cyan); }
.a360-int__rail { display: flex; flex-direction: column; align-items: center; flex: none; }
.a360-int__dot { width: 9px; height: 9px; border-radius: 50%; margin-top: 3px; }
.a360-int__reason { font-size: 12px; font-weight: 700; color: var(--ci-text); }
.a360-int__meta { font-size: 10.5px; color: var(--ci-text-faint); margin-top: 1px; }

/* competition exposure bar */
.a360-expo { position: relative; height: 12px; border-radius: 6px; background: rgba(18,38,78,0.07); overflow: hidden; }
.a360-expo__fill { height: 100%; border-radius: 6px; background: var(--ci-grad-cyan); }
.a360-expo__target { position: absolute; top: -3px; width: 2px; height: 18px; background: var(--ci-violet); }

/* compare banner */
.a360-cmp { display: flex; align-items: center; gap: 8px; padding: 7px 12px; margin-bottom: 12px;
 border-radius: 10px; border: 1px solid rgba(217,130,10,0.28); background: var(--ci-amber-soft); font-size: 12px; color: var(--ci-text); }
","import React from "react";

// ---------- Stylized region hex map ----------
// Abstract geographic grid: each region is a hex, color intensity = potential, size cue via ring
const HEX = [
 { q: 2, r: 0 }, { q: 3, r: 0 }, { q: 1, r: 1 }, { q: 2, r: 1 },
 { q: 3, r: 1 }, { q: 1, r: 2 }, { q: 2, r: 2 }, { q: 3, r: 2 },
];
export function RegionMap({ regions, onSelect, selected }:
 { regions: { region: string; talent: number; potential: number; growth: number }[];
 onSelect?: (r: string) => void; selected?: string }) {
 const s = 30; // hex radius
 const hexPts = (cx: number, cy: number) =>
 Array.from({ length: 6 }, (_, i) => {
 const a = (Math.PI / 3) * i - Math.PI / 6;
 return `${(cx + s * Math.cos(a)).toFixed(1)},${(cy + s * Math.sin(a)).toFixed(1)}`;
 }).join(" ");
 const maxT = Math.max(...regions.map(r => r.talent));
 return (
 <svg className="ci-chart" viewBox="0 0 300 220" style={{ maxWidth: 340 }}>
 {regions.map((reg, i) => {
 const hx = HEX[i % HEX.length];
 const cx = 40 + hx.q * (s * 1.6) + (hx.r % 2) * (s * 0.8);
 const cy = 34 + hx.r * (s * 1.5);
 const t = reg.potential / 100;
 const sel = selected === reg.region;
 return (
 <g key={reg.region} style={{ cursor: "pointer" }} onClick={() => onSelect?.(reg.region)}>
 <polygon points={hexPts(cx, cy)}
 fill={`rgba(53,224,255,${(0.12 + t * 0.7).toFixed(2)})`}
 stroke={sel ? "var(--ci-cyan)" : "rgba(120,160,220,0.25)"} strokeWidth={sel ? 2.4 : 1}
 style={{ filter: sel ? "drop-shadow(0 0 8px var(--ci-cyan))" : "none", transition: "all .2s" }}>
 <title>{reg.region}: {reg.talent.toLocaleString()} tracked · potential {reg.potential} · growth {reg.growth}%</title>
 </polygon>
 <text x={cx} y={cy - 2} textAnchor="middle" fontSize="8.5" fontWeight="600" fill={t > 0.6 ? "#04121e" : "var(--ci-text)"}>{reg.region}</text>
 <text x={cx} y={cy + 9} textAnchor="middle" fontSize="7.5" fill={t > 0.6 ? "#0a2233" : "var(--ci-text-faint)"}>{(reg.talent / 1000).toFixed(1)}k</text>
 </g>
 );
 })}
 </svg>
 );
}

// ---------- Percentile distribution (bell curve with marker) ----------
export function Distribution({ marker = 84, height = 150 }: { marker?: number; height?: number }) {
 const w = 300, h = height, pad = 10;
 const bell = (x: number) => Math.exp(-Math.pow((x - 50) / 20, 2) / 2);
 const pts: Array<[number, number]> = [];
 for (let i = 0; i <= 60; i++) {
 const x = (i / 60) * 100;
 pts.push([pad + (x / 100) * (w - pad * 2), h - pad - bell(x) * (h - pad * 2)]);
 }
 const line = pts
 .map((p, i) => `${i ? "L" : "M"}${p[0].toFixed(1)} ${p[1].toFixed(1)}`)
 .join(" ");
 const mx = pad + (marker / 100) * (w - pad * 2);
 return (
 <svg className="ci-chart" viewBox={`0 0 ${w} ${h}`}>
 <defs><linearGradient id="distg" x1="0" y1="0" x2="0" y2="1">
 <stop offset="0%" stopColor="var(--ci-cyan)" stopOpacity="0.3" />
 <stop offset="100%" stopColor="var(--ci-cyan)" stopOpacity="0" /></linearGradient></defs>
 <path d={`${line} L ${w - pad} ${h - pad} L ${pad} ${h - pad} Z`} fill="url(#distg)" />
 <path d={line} fill="none" stroke="var(--ci-cyan)" strokeWidth="2" />
 <line x1={mx} y1={pad} x2={mx} y2={h - pad} stroke="var(--ci-amber)" strokeWidth="2" strokeDasharray="3 3" />
 <circle cx={mx} cy={pad + 2} r="4" fill="var(--ci-amber)" />
 <text x={mx} y={pad - 1} textAnchor="middle" fontSize="9" fill="var(--ci-amber)">P{marker}</text>
 </svg>
 );
}

// ---------- Trajectory bands (projection cone) ----------
export function Trajectory({ data, height = 200 }:
 { data: { m: number; low: number; mid: number; high: number; actual: number | null }[]; height?: number }) {
 const w = 560, h = height, pad = 24, n = data.length;
 const X = (i: number) => pad + (i / (n - 1)) * (w - pad * 2);
 const Y = (v: number) => h - pad - (v / 100) * (h - pad * 2);
 const top = data.map((d, i) => `${X(i)} ${Y(d.high)}`).join(" L ");
 const bot = [...data].reverse().map((d, i) => `${X(n - 1 - i)} ${Y(d.low)}`).join(" L ");
 const mid = data.map((d, i) => (i ? "L" : "M") + X(i) + " " + Y(d.mid)).join(" ");
 const act = data.filter(d => d.actual != null).map((d, i) => (i ? "L" : "M") + X(d.m) + " " + Y(d.actual!)).join(" ");
 return (
 <svg className="ci-chart" viewBox={`0 0 ${w} ${h}`}>
 {[0, 0.5, 1].map(g => <line key={g} x1={pad} x2={w - pad} y1={pad + g * (h - pad * 2)} y2={pad + g * (h - pad * 2)} stroke="var(--ci-grid-line)" />)}
 <path d={`M ${top} L ${bot} Z`} fill="var(--ci-violet)" fillOpacity="0.12" />
 <path d={mid} fill="none" stroke="var(--ci-violet)" strokeWidth="1.6" strokeDasharray="4 4" opacity="0.7" />
 <path d={act} fill="none" stroke="var(--ci-cyan)" strokeWidth="2.6" strokeLinecap="round"
 style={{ filter: "drop-shadow(0 0 5px var(--ci-cyan))" }} />
 {data.filter(d => d.actual != null).map(d => <circle key={d.m} cx={X(d.m)} cy={Y(d.actual!)} r="2.6" fill="var(--ci-cyan)" />)}
 <text x={pad} y={h - 6}>Now</text>
 <text x={w - pad} y={h - 6} textAnchor="end">+11 mo projection</text>
 </svg>
 );
}
