import type { Status } from './demo'

const spark = (seed: number, n = 16) => {
 let s = seed
 const r = () => (s = (s * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff
 let v = 40 + r() * 20
 return Array.from({ length: n }, () => (v = Math.max(8, Math.min(96, v + (r() - 0.42) * 15))))
}

