","import React from "react";

// ---------- Layered Sankey-style flow ----------
export function SankeyFlow({ nodes, links, height = 260 }:
 { nodes: string[]; links: { s: number; t: number; v: number }[]; height?: number }) {
 const w = 560, h = height, pad = 8;
 // compute layer per node (longest path from a pure source)
 const layer = nodes.map(() => 0);
 for (let k = 0; k < nodes.length; k++)
 links.forEach(l => { if (layer[l.t] < layer[l.s] + 1) layer[l.t] = layer[l.s] + 1; });
 const maxLayer = Math.max(...layer);
 const byLayer: number[][] = Array.from({ length: maxLayer + 1 }, () => []);
 layer.forEach((L, i) => byLayer[L].push(i));
 const pos = nodes.map(() => ({ x: 0, y: 0, h: 0 }));
 const COLORS = ["#35e0ff", "#4d8dff", "#34e3a4", "#9a7bff", "#2fe6c4", "#ffc24b", "#35e0ff", "#ff8fa3"];
 byLayer.forEach((ids, L) => {
 const total = ids.reduce((s, i) => s + Math.max(nodeVal(i), 6), 0);
 let y = pad;
 ids.forEach(i => {
 const nh = (Math.max(nodeVal(i), 6) / total) * (h - pad * 2) - 8;
 pos[i] = { x: pad + (L / maxLayer) * (w - pad * 2 - 12), y, h: Math.max(nh, 14) };
 y += Math.max(nh, 14) + 10;
 });
 });
 function nodeVal(i: number) {
 const out = links.filter(l => l.s === i).reduce((s, l) => s + l.v, 0);
 const inc = links.filter(l => l.t === i).reduce((s, l) => s + l.v, 0);
 return Math.max(out, inc);
 }
 const srcOff: Record<number, number> = {}, tgtOff: Record<number, number> = {};
 const nw = 11;
 return (
 <svg className="ci-chart" viewBox={`0 0 ${w} ${h}`}>
 {links.map((l, i) => {
 const so = srcOff[l.s] || 0, to = tgtOff[l.t] || 0;
 const sv = pos[l.s], tv = pos[l.t];
 const th = (l.v / nodeVal(l.s)) * sv.h;
 const th2 = (l.v / nodeVal(l.t)) * tv.h;
 const x1 = sv.x + nw, y1 = sv.y + so + th / 2;
 const x2 = tv.x, y2 = tv.y + to + th2 / 2;
 srcOff[l.s] = so + th; tgtOff[l.t] = to + th2;
 const mx = (x1 + x2) / 2;
 return <path key={i} d={`M${x1} ${y1} C${mx} ${y1} ${mx} ${y2} ${x2} ${y2}`}
 fill="none" stroke={COLORS[l.s % COLORS.length]} strokeOpacity="0.28"
 strokeWidth={Math.max(th, 2)} style={{ transition: "stroke-opacity .2s" }}>
 <title>{nodes[l.s]} → {nodes[l.t]}: {l.v}</title>
 </path>;
 })}
 {nodes.map((n, i) => (
 <g key={i}>
 <rect x={pos[i].x} y={pos[i].y} width={nw} height={pos[i].h} rx="3"
 fill={COLORS[i % COLORS.length]} />
 <text x={pos[i].x + (layer[i] === maxLayer ? -6 : nw + 6)} y={pos[i].y + pos[i].h / 2}
 textAnchor={layer[i] === maxLayer ? "end" : "start"} dominantBaseline="middle" fontSize="9.5"
 fill="var(--ci-text-dim)">{n}</text>
 </g>
 ))}
 </svg>
 );
}
